199			{"plain", `{}`},
200		}
201		for _, tc := range cases {
202			cfg := mustParseConfig(t, explainCfg)
203			flag := cfg.Find(tc.key)
204			ctx := mustParseContext(t, tc.ctx)
205			plain := flag.Evaluate(ctx)
206			explained := flag.EvaluateExplain(ctx)
207			if !explained.EvalResult.Equals(plain) {
