220		var m map[string]any
221		if err := json.Unmarshal(out, &m); err != nil {
222			t.Fatalf("explain output is not JSON: %s (%v)", out, err)
223		}
224		for _, k := range []string{"key", "value", "reason", "ruleId", "explanation"} {
225			if _, ok := m[k]; !ok {
