255	// 不会变成新字段。配置与上下文各自用直接/转义两种写法，输出逐字节一致。
256	func TestExplainQuotesBackslashControlRoundTrip(t *testing.T) {
257		attr := "属\"性\\名"
258		value := "行一\n行二\t制表\"引号\\反斜杠🚀"
