263				t.Run(cfgSpelling+"-config/"+ctxSpelling+"-context", func(t *testing.T) {
264					j := func(s string) string { return specialJSON(t, cfgSpelling, s) }
265					jc := func(s string) string { return specialJSON(t, ctxSpelling, s) }
266					cfgRaw := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
