22	// escapeJSONString 把文字写成 JSON \uXXXX 转义序列（非 BMP 字符用代理项对，
23	// 引号、反斜杠与控制字符按 JSON 规则转义），得到与直接书写字符同义的 JSON
24	// 字符串内容（不含两侧引号）。
25	func escapeJSONString(s string) string {
26		var b strings.Builder
27		for _, r := range s {
28			switch {
29			case r == '"':
30				b.WriteString(`\"`)
31			case r == '\\':
32				b.WriteString(`\\`)
33			case r < 0x20:
34				fmt.Fprintf(&b, `\u%04X`, r)
35			case r < 0x80:
36				b.WriteRune(r)
37			case r <= 0xFFFF:
38				fmt.Fprintf(&b, `\u%04X`, r)
39			default:
40				r -= 0x10000
41				fmt.Fprintf(&b, `\u%04X\u%04X`, 0xD800+(r>>10), 0xDC00+(r&0x3FF))
42			}
43		}
44		return b.String()
45	}
46	
47	// cliSpecialJSON 按写法把文字写入 JSON 字符串字面量：direct 直接书写字符，
48	// escaped 把非 ASCII 与控制字符全部写成 \uXXXX——两种写法解码后是同一文字。
49	func cliSpecialJSON(t *testing.T, spelling, s string) string {
50		t.Helper()
51		switch spelling {
52		case "direct":
53			b, err := json.Marshal(s)
54			if err != nil {
55				t.Fatalf("marshal %q: %v", s, err)
56			}
57			return string(b)
58		case "escaped":
59			return `"` + escapeJSONString(s) + `"`
60		default:
61			t.Fatalf("unknown spelling %q", spelling)
62			return ""
63		}
64	}
