66	// cliSpecialConfig 的开关按顺序含三条规则：r-跳过é🚀 因 标签🏷 不命中而整体
67	// 不成立（两个条件的逐条判断都要保留），r-定案🚀 命中并返回 false 定案，
68	// r-隐身 不再被考虑。所有名称与比较内容都含中文、重音字符与表情。
69	func cliSpecialConfig(t *testing.T, spelling string) string {
70		t.Helper()
71		j := func(s string) string { return cliSpecialJSON(t, spelling, s) }
72		return `{"flags":[{"key":` + j(cliSpecialKey) + `,"enabled":true,"default":true,"rules":[` +
