82	// cliSpecialContext 让首条规则因 标签🏷 不命中而整体不成立、第二条规则命中。
83	func cliSpecialContext(t *testing.T, spelling string) string {
84		t.Helper()
85		j := func(s string) string { return cliSpecialJSON(t, spelling, s) }
86		return `{` + j("套餐é") + `:` + j("专业版 🚀") + `,` +
87			j("标签🏷") + `:` + j("其他") + `,` +
88			j("地区") + `:` + j("北京🚀") + `}`
