306	// TestInExactStringBoundaries 验证外形相近但解码后不相等的字符串不得归入列表：
307	// 大小写、首尾空白、预组合 é（U+00E9）与 "e 加 U+0301" 的序列、邻近码位的
308	// 表情符号都按原样区分。列表明确包含组合序列时，才匹配该序列。
309	func TestInExactStringBoundaries(t *testing.T) {
310		cfg := inCfg(`tier`, `["é","😀","AbC"]`)
311		misses := []struct {
312			name string
313			raw  string
314		}{
315			{"uppercase precomposed", `{"tier":"É"}`},
316			{"lowercase ascii", `{"tier":"abc"}`},
317			{"leading space", `{"tier":" é"}`},
318			{"trailing space", `{"tier":"é "}`},
319			{"combining sequence vs precomposed", `{"tier":"` + inEscCombine + `"}`},
320			{"replacement char", `{"tier":"` + inEscReplace + `"}`},
321			{"neighboring emoji code point", `{"tier":"😃"}`},
322			{"missing attribute", `{"other":"é"}`},
323		}
324		for _, tc := range misses {
325			t.Run(tc.name, func(t *testing.T) {
326				got := eval(t, cfg, "f", tc.raw)
327				if got.Reason != EvalDefault || got.RuleID != nil || got.Value {
328					t.Fatalf("lookalike must not belong to the list: got %+v", got)
329				}
330			})
331		}
332	
333		// 列表明确包含 e + U+0301：组合序列命中，预组合 é 反而不命中。
334		cfgCombining := inCfg(`tier`, `["`+inEscCombine+`"]`)
335		if got := eval(t, cfgCombining, "f", `{"tier":"`+inEscCombine+`"}`); got.Reason != EvalRule || !got.Value {
336			t.Fatalf("explicit combining sequence must match itself: %+v", got)
337		}
338		if got := eval(t, cfgCombining, "f", `{"tier":"é"}`); got.Reason != EvalDefault {
339			t.Fatalf("precomposed é must not match an e+U+0301 list: %+v", got)
340		}
341	}
342	
343	// TestInEscapedBackslashIsLiteralText 保护“转义只发生一次”：JSON 中的
344	// "\\u00E9" 解码为反斜杠加 u00E9 的普通文本，其后即使跟着 u 和十六进制数字也
345	// 不会再次解码；它只与相同的字面文本相等，与真正解码出的 é 互不命中。
346	func TestInEscapedBackslashIsLiteralText(t *testing.T) {
347		cfg := inCfg(`tier`, `["\\u00E9","\\uD83D\\uDE00"]`)
348		// 上下文给出相同的字面文本：命中。
349		if got := eval(t, cfg, "f", `{"tier":"\\u00E9"}`); got.Reason != EvalRule || !got.Value {
350			t.Fatalf("escaped-backslash text must equal the same literal text: %+v", got)
351		}
352		if got := eval(t, cfg, "f", `{"tier":"\\uD83D\\uDE00"}`); got.Reason != EvalRule || !got.Value {
353			t.Fatalf("surrogate-shaped literal text must equal itself: %+v", got)
354		}
355		// 真正解码出的字符（直接写出或用合法 Unicode 转义）与该字面文本不同。
356		for _, ctxRaw := range []string{`{"tier":"é"}`, `{"tier":"` + inEscEAcute + `"}`} {
357			if got := eval(t, cfg, "f", ctxRaw); got.Reason != EvalDefault {
358				t.Fatalf("decoded é must not equal backslash literal text (%s): %+v", ctxRaw, got)
359			}
360		}
361		if got := eval(t, cfg, "f", `{"tier":"😀"}`); got.Reason != EvalDefault {
362			t.Fatalf("decoded emoji must not equal surrogate-shaped literal text: %+v", got)
363		}
364		// 反向：列表只有解码后的 é 时，反斜杠字面文本不属于列表。
365		cfgDecoded := inCfg(`tier`, `["é"]`)
366		if got := eval(t, cfgDecoded, "f", `{"tier":"\\u00E9"}`); got.Reason != EvalDefault {
367			t.Fatalf("literal backslash text must not match a decoded-only list: %+v", got)
